/** A style's widths, decoded once: character (from 32) x size (from 11px). */
const decoded = new Map();
let exceptionLists = null;
function decode(index) {
  let w = decoded.get(index);
  if (w) return w;
  exceptionLists = exceptionLists || EXCEPTIONS.split('|');
  const exceptions = exceptionLists[index];
  const base = BASES.slice(index * 2 * (LAST - FIRST + 1), (index + 1) * 2 * (LAST - FIRST + 1));
  w = new Uint8Array((LAST - FIRST + 1) * N);
  for (let k = 0; k <= LAST - FIRST; k++) {
    const b = ((base.charCodeAt(2 * k) - 48) << 6) | (base.charCodeAt(2 * k + 1) - 48);
    for (let i = 0; i < N; i++) w[k * N + i] = (b * (PX_FROM + i) + 1024) >> 11;
  }
  for (let k = 0, j = 0; j < exceptions.length; j++) {
    if (exceptions[j] === ' ') { k++; continue; }
    w[k * N + exceptions.charCodeAt(j) - 48] += exceptions.charCodeAt(++j) - 80;
  }
  decoded.set(index, w);
  return w;
}

/** Small Fonts in each style: per character, its width at 5 to 10px, and what a line takes beyond its characters
 *  at each (the overhang Windows gives a bold or an italic it makes up of a bitmap font). */
const SMALL = {"regular":{"widths":"11122222222333344433566644446644557933556711222222333322333322333422444622222322333522222333333333455633333433455633455633455633445633455633445633455633455622222322222333345633345633345633355655789:","more":[0,0,0,0,0,0]},"bold":{"widths":"22233333333444455544677755557755668:4466782233333344443344443344453355573333343344463333344444444456674444454456674456674456674455674456674455674456674456673333343333344445674445674445674446676689:;5567885567885567885567885556774456775567895566883333334455665566784455676679:955678855678955668855678955678844667855567755677855577866799:555778555778445677334444334444334444445554445667334444445567445667445567445667445567444444445667445567333333333333445566333333557799445567445677445667445667444444444566334444445567445566556778445556445556445556334444223334224444445564","more":[1,1,1,1,1,1]},"italic":{"widths":"11122222222333344433566644446644557933556711222222333322333322333422444622222322333522222333333333455633333433455633455633455633445633455633445633455633455622222322222333345633345633345633355655789:","more":[2,2,3,4,5,5]},"boldItalic":{"widths":"22233333333444455544677755557755668:4466782233333344443344443344453355573333343344463333344444444456674444454456674456674456674455674456674455674456674456673333343333344445674445674445674446676689:;5567885567885567885567885556774456775567895566883333334455665566784455676679:955678855678955668855678955678844667855567755677855577866799:555778555778445677334444334444334444445554445667334444445567445667445567445667445567444444445667445567333333333333445566333333557799445567445677445667445667444444444566334444445567445566556778445556445556445556334444223334224444445564","more":[3,3,4,5,6,6]}};

/** Excel's character widths for font `name` at `px` pixels (its size in points x 4/3), bold or italic or both:
 *  { width(code), digit, more, small }, or null when the table hasn't the font or the size. `width(code)` is a
 *  character's whole pixels, -1 for one outside printable ASCII; `digit` the width of 0; `more` the pixels a line
 *  takes beyond its characters (an italic's, and a made-up bold's under 8pt). Sizes that round to 10px or less
 *  are Small Fonts' whatever the font (`small`). */
export function excelWidths(name, px, bold = false, italic = false) {
  const size = Math.round(px);
  const style = bold ? (italic ? 'boldItalic' : 'bold') : italic ? 'italic' : 'regular';
  let width;
  let more = 0;
  if (size <= SMALL_TO) {
    const at = Math.max(SMALL_FROM, size) - SMALL_FROM;
    const s = SMALL[style].widths;
    const n = SMALL_TO - SMALL_FROM + 1;
    more = SMALL[style].more[at];
    width = (code) => (code >= FIRST && code <= LAST ? s.charCodeAt((code - FIRST) * n + at) - 48 : -1);
  } else {
    const lower = String(name).toLowerCase();
    const table = Object.hasOwn(WIDTHS, lower) ? WIDTHS[lower] : null; // (not Object's own constructor or __proto__)
    if (!table || size > PX_TO) return null;
    const at = size - PX_FROM;
    const w = decode(table[style] ?? (bold ? table.bold : null) ?? table.regular);
    if (italic) more = table.more[bold ? 1 : 0].charCodeAt(at) - 48;
    width = (code) => (code >= FIRST && code <= LAST ? w[(code - FIRST) * N + at] : -1);
  }
  return { width, digit: width(48), more, small: size <= SMALL_TO };
}
